# P2 but keep stopwords
P2_KEEP_STOPWORDS = {
    **P2_CONFIG,
    "remove_stopwords": False,
}

# P2 but turn lemmatization off
P2_NO_LEMMA = {
    **P2_CONFIG,
    "lemmatize": False,
}

# P2 but disable hashtag Wordninja segmentation
P2_NO_HASHTAG_SPLIT = {
    **P2_CONFIG,
    "hashtag_segmentation_mode": "none",
}

# P1 plus lemmatization only (no P2 stopword removal / hashtag segmentation)
P1_PLUS_LEMMA = {
    **P1_CONFIG,
    "lemmatize": True,
    "spacy_model": "en_core_web_sm",
}

VARIANTS = {
    "P0": P0_CONFIG,
    "P1": P1_CONFIG,
    "P2": P2_CONFIG,
    "P2_keep_stopwords": P2_KEEP_STOPWORDS,
    "P2_no_lemma": P2_NO_LEMMA,
    "P2_no_hashtag_split": P2_NO_HASHTAG_SPLIT,
    "P1_plus_lemma": P1_PLUS_LEMMA,
}

for name, cfg in VARIANTS.items():
    print(name, "->", cfg)

